import {modelBadge} from './model-identity.js?v=20261101-short1';
import {completionBody} from './completed-suite.js?v=20261101-short1';
import {weightedGrade,RECEIPT_REVIEW_RULE} from './weighted-score.js?v=20261101-short1';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function gradeReceiptAnswer(answer){
  const s=String(answer).normalize('NFKC').trim().replace(/[。.!！\s]/g,'');
  const hit=s.match(/^(?:辣椒炒肉)?(?:一共|总共|共|有|是)?([一二两三四五六七八九十\d]+)(?:份)?$/);
  if(!hit)return {state:'review',score:null,label:'待人工复核',reason:'没有唯一、明确的数量结论，不能自动猜测模型意图。'};
  const correct=['1','一'].includes(hit[1]);return {state:correct?'pass':'fail',score:correct?20:0,label:correct?'通过':'未通过',reason:correct?'明确回答1份，符合本题参考答案。':'明确数量不符合本题参考答案1份。'};
}
export function validateReceiptTask(t){if(t?.schemaVersion!=='receipt-vision-bank-v2'||t.suiteId!=='zhufeng-receipt-vision-v1'||t.image!=='assets/receipt-chilli-pork.png'||!/^\w{64}$/.test(t.imageSha256)||t.reference?.quantity!==1||t.reference?.source!=='user-provided-answer'||!['not_run','defined'].includes(t.status))throw Error('账单题文件不符合约定');return t;}
export const receiptTeaser=(completed=false)=>`<article class="checkup-card receipt-teaser"><a class="question-card-link" href="#checkup/receipt"><span class="question-number">07</span><div><span class="question-category">账单整活 · 20分${completed?'':' · 待测'}</span><h3>账单里的辣椒炒肉，到底几份？</h3></div><span class="question-arrow" aria-hidden="true">→</span></a></article>`;
export function receiptView(task,models,suite=null){return `<div class="page-head"><div><div class="eyebrow">逐风 / VISION CHECK 07</div><h1>这张账单，<br>能坑住你的 AI 吗？</h1><p class="subtitle">一张账单，各模型的实际回答。</p></div><a class="button-link" href="#checkup">← 返回测试集</a></div><div class="receipt-layout"><figure><img src="${e(task.image)}" alt="用户提供的餐厅点菜单原图，包含中英菜名与右侧数量列" width="1320" height="1149"><figcaption>出题者提供的原图 · 未修改 <a href="${e(task.image)}" download="receipt-chilli-pork.png">下载原图 ↓</a></figcaption></figure><div class="receipt-instructions"><span class="section-index">THE QUESTION</span><h2>${e(task.prompt)}</h2><p class="receipt-game-note">这是一道整活题，按出题者约定的“1份”计分。</p><button data-receipt-copy>复制提问</button><p class="evidence-meta" role="status" id="receipt-copy-status"></p><ol><li>下载并附上左侧原图。</li><li>把上面的提问一起发给支持图片输入的模型。</li><li>保留模型、入口、时间、原始回答与图片，计入八项百分制的20分图像识别项。</li></ol><details class="pub-conditions"><summary>图片输入与测试条件</summary><p>测试需附上原图。实际输入、推理档位和交付状态见各模型的测试记录。</p></details><details class="receipt-reference"><summary>展开参考答案与评分</summary><p>${e(task.reference.explanation)}</p><ul><li>${e(task.rubric.correct)}</li><li>${e(task.rubric.wrong)}</li><li>${e(task.rubric.pending)}</li></ul><p>本题约定：1份得20分，2份或其他错误数量得0分。分数只对应这道整活题，原图和模型原话都保留，欢迎不同解读。</p><p>${e(RECEIPT_REVIEW_RULE)}</p></details></div></div><section class="traffic-panel"><h2>这道题的模型成绩</h2><p class="evidence-meta">${e(task.note)}</p>${['daily-weighted-v3','daily-weighted-v4','daily-weighted-v5'].includes(suite?.schemaVersion)?models.map(m=>{const row=suite.models.find(r=>r.modelId===m.id);return `<article class="panel"><div class="panel-head"><h3><a class="model-nameplate" href="#checkup/model/${e(m.id)}">${modelBadge(m.id)}<span>${e(m.name)}</span></a>${m.selectedEffort?' · '+e(m.selectedEffort):''}</h3><span>${weightedGrade(suite,row,6)}分</span></div><div class="panel-body">${completionBody(suite,row,'receipt')}</div></article>`;}).join(''):`<div class="receipt-pending">${models.map(m=>`<div><a class="model-nameplate" href="#checkup/model/${e(m.id)}">${modelBadge(m.id)}<span>${e(m.name)}</span></a><span>待测</span><strong>— / 20</strong></div>`).join('')}</div>`}</section>`;}
export function createReceiptController({main,rerender}){
  let task=null,error='',loading=false;async function load(){loading=true;try{const r=await fetch('data/receipt-test.json');if(!r.ok)throw Error('图片题文件未读到');task=validateReceiptTask(await r.json());}catch(err){error=err.message;}if(location.hash==='#checkup/receipt')rerender();}
  main.addEventListener('click',async ev=>{if(location.hash!=='#checkup/receipt')return;const b=ev.target.closest('button');if(b?.hasAttribute('data-receipt-copy')){const status=main.querySelector('#receipt-copy-status');try{await navigator.clipboard.writeText(task.prompt);status.textContent='已复制；记得同时附上原图。';}catch{status.textContent='请选中上方提问复制，并同时附上原图。';}}if(b?.hasAttribute('data-receipt-grade')){const grade=gradeReceiptAnswer(main.querySelector('#receipt-answer').value);main.querySelector('#receipt-grade').innerHTML=`<p><strong>${e(grade.label)} · ${grade.score===null?'待评':grade.score+' / 20 分'}</strong><br>${e(grade.reason)}</p>`;}});
  return {render(models,suite=null){if(!task&&!error&&!loading)load();return error?`<p>${e(error)}</p>`:task?receiptView(suite?.highOnly?{...task,note:'同一张原图，比较各模型的数量判断。'}:task,models,suite):'<p>正在读取账单图新题…</p>';}};
}
